import React, { useState, useEffect } from 'react';
import { useAuthStore } from '@/store/auth-store';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { toast } from 'sonner';
import api from '@/lib/axios';

interface Bateria {
    id: number;
    marca: string;
    modelo: string;
    arreglo: number;
    costo: number;
    tipo: string;
}

interface EditableBateria extends Bateria {
    isEditing: boolean;
    originalData: Bateria;
}

const ReparacionesConfig = () => {
    const [baterias, setBaterias] = useState<EditableBateria[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [searchTerm, setSearchTerm] = useState('');
    const { isAdmin } = useAuthStore();

    const fetchBaterias = async () => {
        try {
            setLoading(true);
            setError(null);
            const response = await api.get('/api/Baterias/all');
            
            if (response.data.success) {
                const bateriasWithEditing = response.data.data.map((bateria: Bateria) => ({
                    ...bateria,
                    isEditing: false,
                    originalData: { ...bateria }
                }));
                setBaterias(bateriasWithEditing);
            } else {
                throw new Error(response.data.message || 'Error al cargar las baterías');
            }
        } catch (error: any) {
            console.error('Error al obtener baterías:', error);
            const errorMessage = error.response?.data?.message || error.message || 'Error al cargar las baterías';
            setError(errorMessage);
            toast.error(errorMessage);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchBaterias();
    }, []);

    const handleEdit = (id: number) => {
        if (!isAdmin()) {
            toast.error('No tienes permisos para editar');
            return;
        }

        setBaterias(prev => prev.map(bateria => 
            bateria.id === id 
                ? { ...bateria, isEditing: true, originalData: { ...bateria } }
                : bateria
        ));
    };

    const handleCancel = (id: number) => {
        setBaterias(prev => prev.map(bateria => 
            bateria.id === id 
                ? { ...bateria.originalData, isEditing: false, originalData: bateria.originalData }
                : bateria
        ));
    };

    const handleSave = async (id: number) => {
        try {
            const bateria = baterias.find(b => b.id === id);
            if (!bateria) return;

            const response = await api.put(`/api/Baterias/${id}`, {
                id: bateria.id,
                marca: bateria.marca,
                modelo: bateria.modelo,
                arreglo: bateria.arreglo,
                costo: bateria.costo,
                tipo: bateria.tipo
            });

            if (response.data.success) {
                setBaterias(prev => prev.map(b => 
                    b.id === id 
                        ? { ...b, isEditing: false, originalData: { ...b } }
                        : b
                ));
                toast.success('Batería actualizada correctamente');
            } else {
                throw new Error(response.data.message);
            }
        } catch (error: any) {
            console.error('Error al actualizar batería:', error);
            const errorMessage = error.response?.data?.message || error.message || 'Error al actualizar la batería';
            toast.error(errorMessage);
        }
    };

    const handleDelete = async (id: number) => {
        if (!isAdmin()) {
            toast.error('No tienes permisos para eliminar');
            return;
        }

        if (!confirm('¿Estás seguro de que quieres eliminar esta batería?')) {
            return;
        }

        try {
            const response = await api.delete(`/api/Baterias/${id}`);
            
            if (response.data.success) {
                setBaterias(prev => prev.filter(b => b.id !== id));
                toast.success('Batería eliminada correctamente');
            } else {
                throw new Error(response.data.message);
            }
        } catch (error: any) {
            console.error('Error al eliminar batería:', error);
            const errorMessage = error.response?.data?.message || error.message || 'Error al eliminar la batería';
            toast.error(errorMessage);
        }
    };

    const handleInputChange = (id: number, field: keyof Bateria, value: string | number) => {
        setBaterias(prev => prev.map(bateria => 
            bateria.id === id 
                ? { ...bateria, [field]: value }
                : bateria
        ));
    };

    const filteredBaterias = baterias.filter(bateria =>
        bateria.marca.toLowerCase().includes(searchTerm.toLowerCase()) ||
        bateria.modelo.toLowerCase().includes(searchTerm.toLowerCase()) ||
        bateria.tipo.toLowerCase().includes(searchTerm.toLowerCase())
    );

    if (loading) {
        return (
            <div className="flex items-center justify-center min-h-screen">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-gray-900"></div>
            </div>
        );
    }

    if (error) {
        return (
            <div className="flex flex-col items-center justify-center min-h-screen">
                <div className="text-red-600 mb-4">{error}</div>
                <Button onClick={() => fetchBaterias()}>Reintentar</Button>
            </div>
        );
    }

    return (
        <div className="container mx-auto p-4">
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-2xl font-bold">Configuración de Baterías</h1>
                <div className="flex gap-4">
                    <div className="relative">
                        <Input
                            type="text"
                            placeholder="Buscar baterías..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-64"
                        />
                    </div>
                </div>
            </div>

            <div className="bg-white rounded-lg shadow overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="min-w-full divide-y divide-gray-200">
                        <thead className="bg-gray-50">
                            <tr>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                    ID
                                </th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                    Marca
                                </th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                    Modelo
                                </th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                    Tipo
                                </th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                    Precio Reparación
                                </th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                    Costo
                                </th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                    Acciones
                                </th>
                            </tr>
                        </thead>
                        <tbody className="bg-white divide-y divide-gray-200">
                            {filteredBaterias.map((bateria) => (
                                <tr key={bateria.id} className="hover:bg-gray-50">
                                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                        {bateria.id}
                                    </td>
                                    <td className="px-6 py-4 whitespace-nowrap">
                                        {bateria.isEditing ? (
                                            <Input
                                                value={bateria.marca}
                                                onChange={(e) => handleInputChange(bateria.id, 'marca', e.target.value)}
                                                className="w-32"
                                            />
                                        ) : (
                                            <span className="text-sm text-gray-900">{bateria.marca}</span>
                                        )}
                                    </td>
                                    <td className="px-6 py-4 whitespace-nowrap">
                                        {bateria.isEditing ? (
                                            <Input
                                                value={bateria.modelo}
                                                onChange={(e) => handleInputChange(bateria.id, 'modelo', e.target.value)}
                                                className="w-32"
                                            />
                                        ) : (
                                            <span className="text-sm text-gray-900">{bateria.modelo}</span>
                                        )}
                                    </td>
                                    <td className="px-6 py-4 whitespace-nowrap">
                                        {bateria.isEditing ? (
                                            <Input
                                                value={bateria.tipo}
                                                onChange={(e) => handleInputChange(bateria.id, 'tipo', e.target.value)}
                                                className="w-24"
                                            />
                                        ) : (
                                            <span className="text-sm text-gray-900">{bateria.tipo}</span>
                                        )}
                                    </td>
                                    <td className="px-6 py-4 whitespace-nowrap">
                                        {bateria.isEditing ? (
                                            <Input
                                                type="number"
                                                step="0.01"
                                                value={bateria.arreglo}
                                                onChange={(e) => handleInputChange(bateria.id, 'arreglo', parseFloat(e.target.value) || 0)}
                                                className="w-24"
                                            />
                                        ) : (
                                            <span className="text-sm text-gray-900">${bateria.arreglo}</span>
                                        )}
                                    </td>
                                    <td className="px-6 py-4 whitespace-nowrap">
                                        {bateria.isEditing ? (
                                            <Input
                                                type="number"
                                                step="0.01"
                                                value={bateria.costo}
                                                onChange={(e) => handleInputChange(bateria.id, 'costo', parseFloat(e.target.value) || 0)}
                                                className="w-24"
                                            />
                                        ) : (
                                            <span className="text-sm text-gray-900">${bateria.costo}</span>
                                        )}
                                    </td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                                        {bateria.isEditing ? (
                                            <div className="flex gap-2">
                                                <Button
                                                    size="sm"
                                                    onClick={() => handleSave(bateria.id)}
                                                    className="bg-green-600 hover:bg-green-700"
                                                >
                                                    Guardar
                                                </Button>
                                                <Button
                                                    size="sm"
                                                    variant="outline"
                                                    onClick={() => handleCancel(bateria.id)}
                                                >
                                                    Cancelar
                                                </Button>
                                            </div>
                                        ) : (
                                            <div className="flex gap-2">
                                                <Button
                                                    size="sm"
                                                    onClick={() => handleEdit(bateria.id)}
                                                    disabled={!isAdmin()}
                                                >
                                                    Editar
                                                </Button>
                                                <Button
                                                    size="sm"
                                                    variant="destructive"
                                                    onClick={() => handleDelete(bateria.id)}
                                                    disabled={!isAdmin()}
                                                >
                                                    Eliminar
                                                </Button>
                                            </div>
                                        )}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
                
                {filteredBaterias.length === 0 && (
                    <div className="text-center py-8 text-gray-500">
                        {searchTerm ? 'No se encontraron baterías que coincidan con la búsqueda' : 'No hay baterías registradas'}
                    </div>
                )}
            </div>

            <div className="mt-4 text-sm text-gray-600">
                Total de baterías: {filteredBaterias.length}
            </div>
        </div>
    );
};

export default ReparacionesConfig;

