import React, { useState, useEffect } from 'react';

interface SidebarFiltersProps {
  marcas: string[];
  categorias: string[];
  precioMin: number;
  precioMax: number;
  filtros: {
    marcas: string[];
    categorias: string[];
    precio: [number, number];
  };
  onChange: (filtros: {
    marcas: string[];
    categorias: string[];
    precio: [number, number];
  }) => void;
  onClear: () => void;
}

const SidebarFilters: React.FC<SidebarFiltersProps> = ({
  marcas,
  categorias,
  precioMin,
  precioMax,
  filtros,
  onChange,
  onClear
}) => {
  const [precio, setPrecio] = useState<[number, number]>([precioMin, precioMax]);

  useEffect(() => {
    setPrecio(filtros.precio);
  }, [filtros.precio]);

  const handleMarcaChange = (marca: string) => {
    const nuevasMarcas = filtros.marcas.includes(marca)
      ? filtros.marcas.filter(m => m !== marca)
      : [...filtros.marcas, marca];
    onChange({ ...filtros, marcas: nuevasMarcas });
  };

  const handleCategoriaChange = (categoria: string) => {
    const nuevasCategorias = filtros.categorias.includes(categoria)
      ? filtros.categorias.filter(c => c !== categoria)
      : [...filtros.categorias, categoria];
    onChange({ ...filtros, categorias: nuevasCategorias });
  };

  const handlePrecioChange = (idx: 0 | 1, value: number) => {
    const nuevo = [...precio] as [number, number];
    nuevo[idx] = value;
    if (nuevo[0] > nuevo[1]) {
      // No permitir rango invertido
      return;
    }
    setPrecio(nuevo);
    onChange({ ...filtros, precio: nuevo });
  };

  return (
    <aside className="w-full md:w-64 bg-white rounded-lg shadow p-6 mb-6 md:mb-0 md:mr-8">
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-xl font-bold">Filtrar</h2>
        <button
          className="text-blue-600 hover:underline text-sm"
          onClick={onClear}
          aria-label="Limpiar filtros"
        >
          Limpiar
        </button>
      </div>

      {/* Marcas */}
      <div className="mb-6">
        <h3 className="font-semibold mb-2">Marca</h3>
        <div className="flex flex-col gap-1 max-h-32 overflow-y-auto pr-2">
          {marcas.map(marca => (
            <label key={marca} className="inline-flex items-center gap-2 cursor-pointer">
              <input
                type="checkbox"
                checked={filtros.marcas.includes(marca)}
                onChange={() => handleMarcaChange(marca)}
                className="accent-blue-600"
                tabIndex={0}
                aria-label={`Filtrar por marca ${marca}`}
              />
              <span>{marca}</span>
            </label>
          ))}
        </div>
      </div>

      {/* Categorías */}
      <div className="mb-6">
        <h3 className="font-semibold mb-2">Categoría</h3>
        <div className="flex flex-col gap-1 max-h-32 overflow-y-auto pr-2">
          {categorias.map(cat => (
            <label key={cat} className="inline-flex items-center gap-2 cursor-pointer">
              <input
                type="checkbox"
                checked={filtros.categorias.includes(cat)}
                onChange={() => handleCategoriaChange(cat)}
                className="accent-blue-600"
                tabIndex={0}
                aria-label={`Filtrar por categoría ${cat}`}
              />
              <span>{cat}</span>
            </label>
          ))}
        </div>
      </div>

      {/* Precio */}
      <div className="mb-6">
        <h3 className="font-semibold mb-2">Precio</h3>
        <div className="flex items-center gap-2">
          <input
            type="number"
            min={precioMin}
            max={precio[1]}
            value={precio[0]}
            onChange={e => handlePrecioChange(0, Number(e.target.value))}
            className="w-20 border rounded p-1 text-sm"
            aria-label="Precio mínimo"
          />
          <span className="mx-1">-</span>
          <input
            type="number"
            min={precio[0]}
            max={precioMax}
            value={precio[1]}
            onChange={e => handlePrecioChange(1, Number(e.target.value))}
            className="w-20 border rounded p-1 text-sm"
            aria-label="Precio máximo"
          />
        </div>
        <div className="text-xs text-gray-500 mt-1">
          Rango: ${precioMin.toLocaleString()} - ${precioMax.toLocaleString()}
        </div>
      </div>
    </aside>
  );
};

export default SidebarFilters; 