import React, { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Label } from '@/components/ui/label';
import { PencilIcon, TrashIcon, PlusIcon } from '@heroicons/react/24/outline';
import axios from '@/lib/axios';
import { toast } from 'sonner';
import VarianteForm from '@/components/admin/VarianteForm';
import EditVarianteForm from '@/components/admin/EditVarianteForm';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";

interface Producto {
  id: number;
  marca: string;
  modelo: string;
  categoria: string;
  img: string;
}

interface Variante {
  id: number;
  ram: string;
  almacenamiento: string;
  color: string;
  precio: number;
  stock: number;
  productoId: number;
}

const Variantes = () => {
  const [productos, setProductos] = useState<Producto[]>([]);
  const [variantes, setVariantes] = useState<Variante[]>([]);
  const [selectedProductoId, setSelectedProductoId] = useState<number | null>(null);
  const [selectedProducto, setSelectedProducto] = useState<Producto | null>(null);
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [selectedVariante, setSelectedVariante] = useState<Variante | null>(null);
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
  const [varianteToDelete, setVarianteToDelete] = useState<Variante | null>(null);
  const [loading, setLoading] = useState(false);

  const fetchProductos = async () => {
    try {
      const response = await axios.get('/api/Producto');
      console.log('Productos obtenidos:', response.data);
      setProductos(response.data);
    } catch (error) {
      console.error('Error al obtener productos:', error);
      toast.error('Error al cargar los productos');
    }
  };

  const fetchVariantes = async (productoId: number) => {
    try {
      console.log('Solicitando variantes para producto ID:', productoId);
      const response = await axios.get(`/api/Producto/${productoId}/variantes`);
      console.log('Variantes obtenidas:', response.data);
      console.log('Tipo de respuesta:', typeof response.data);
      console.log('Es array:', Array.isArray(response.data));
      console.log('Longitud:', response.data?.length);
      
      // La respuesta siempre debe ser un array ahora
      setVariantes(response.data || []);
    } catch (error: any) {
      console.error('Error al obtener variantes:', error);
      console.error('Respuesta del servidor:', error.response?.data);
      console.error('Status:', error.response?.status);
      
      toast.error('Error al cargar las variantes');
      setVariantes([]);
    }
  };

  useEffect(() => {
    fetchProductos();
  }, []);

  useEffect(() => {
    if (selectedProductoId) {
      console.log('Producto seleccionado ID:', selectedProductoId);
      fetchVariantes(selectedProductoId);
      const producto = productos.find(p => p.id === selectedProductoId);
      console.log('Producto encontrado:', producto);
      setSelectedProducto(producto || null);
    } else {
      setVariantes([]);
      setSelectedProducto(null);
    }
  }, [selectedProductoId, productos]);

  const handleProductoChange = (productoId: string) => {
    console.log('Cambiando producto a ID:', productoId);
    setSelectedProductoId(Number(productoId));
  };

  const handleEdit = (variante: Variante) => {
    setSelectedVariante(variante);
    setIsEditModalOpen(true);
  };

  const handleDelete = async (variante: Variante) => {
    setVarianteToDelete(variante);
    setIsDeleteDialogOpen(true);
  };

  const confirmDelete = async () => {
    if (!varianteToDelete) return;

    try {
      setLoading(true);
      await axios.delete(`/api/Producto/variante/${varianteToDelete.id}`);
      toast.success('Variante eliminada exitosamente');
      if (selectedProductoId) {
        await fetchVariantes(selectedProductoId);
      }
    } catch (error) {
      console.error('Error al eliminar variante:', error);
      toast.error('Error al eliminar la variante');
    } finally {
      setLoading(false);
      setIsDeleteDialogOpen(false);
      setVarianteToDelete(null);
    }
  };

  const handleSuccess = () => {
    if (selectedProductoId) {
      fetchVariantes(selectedProductoId);
    }
  };

  // Debug: Mostrar información de diagnóstico
  //console.log('Estado actual:');
  //console.log('- Productos:', productos.length);
  //console.log('- Producto seleccionado ID:', selectedProductoId);
  //console.log('- Variantes:', variantes.length);
  //console.log('- Variantes data:', variantes);

  return (
    <div className="container mx-auto py-6">
      <div className="mb-6">
        <h1 className="text-2xl font-bold mb-4">Gestión de Variantes</h1>
        
        {/* Debug info */}
       {/* <div className="mb-4 p-4 bg-yellow-50 border border-yellow-200 rounded-lg">
          <h3 className="font-semibold text-yellow-800 mb-2">Información de Diagnóstico:</h3>
          <p className="text-sm text-yellow-700">Productos cargados: {productos.length}</p>
          <p className="text-sm text-yellow-700">Producto seleccionado ID: {selectedProductoId || 'Ninguno'}</p>
          <p className="text-sm text-yellow-700">Variantes cargadas: {variantes.length}</p>
          {variantes.length > 0 && (
            <p className="text-sm text-yellow-700">Primera variante: {JSON.stringify(variantes[0])}</p>
          )}
        </div> */}
        
        <div className="bg-white p-6 rounded-lg shadow-md">
          <div className="space-y-4">
            <div>
              <Label htmlFor="producto">Seleccionar Producto</Label>
              <Select
                value={selectedProductoId?.toString() || ''}
                onValueChange={handleProductoChange}
              >
                <SelectTrigger className="mt-2">
                  <SelectValue placeholder="Selecciona un producto" />
                </SelectTrigger>
                <SelectContent>
                  {productos.map((producto) => (
                    <SelectItem key={producto.id} value={producto.id.toString()}>
                      {producto.marca} {producto.modelo} - {producto.categoria}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {selectedProducto && (
              <div className="flex items-center gap-4 p-4 bg-gray-50 rounded-lg">
                <img
                  src={`data:image/jpeg;base64,${selectedProducto.img}`}
                  alt={`${selectedProducto.marca} ${selectedProducto.modelo}`}
                  className="h-16 w-16 object-cover rounded"
                />
                <div>
                  <h3 className="font-semibold text-lg">
                    {selectedProducto.marca} {selectedProducto.modelo}
                  </h3>
                  <p className="text-gray-600 capitalize">{selectedProducto.categoria}</p>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>

      {selectedProducto && (
        <>
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-xl font-semibold">Variantes del Producto</h2>
            <Button onClick={() => setIsCreateModalOpen(true)}>
              <PlusIcon className="h-5 w-5 mr-2" />
              Nueva Variante
            </Button>
          </div>

          <div className="bg-white shadow-md rounded-lg overflow-hidden">
            {variantes.length === 0 ? (
              <div className="p-8 text-center text-gray-500">
                <p>No hay variantes para este producto.</p>
                <p className="text-sm mt-2">Haz clic en Nueva Variante para agregar la primera.</p>
              </div>
            ) : (
              <table className="min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Especificaciones
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Precio
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Stock
                    </th>
                    <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Acciones
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {variantes.map((variante) => (
                    <tr key={variante.id}>
                      <td className="px-6 py-4">
                        <div className="text-sm font-medium text-gray-900">
                          {variante.ram} - {variante.almacenamiento}
                        </div>
                        <div className="text-sm text-gray-500">{variante.color}</div>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <div className="text-sm font-medium text-gray-900">
                          ${variante.precio.toLocaleString()}
                        </div>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${
                          variante.stock > 0 
                            ? 'bg-green-100 text-green-800' 
                            : 'bg-red-100 text-red-800'
                        }`}>
                          {variante.stock}
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleEdit(variante)}
                          className="text-blue-600 hover:text-blue-900 mr-2"
                        >
                          <PencilIcon className="h-5 w-5" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleDelete(variante)}
                          className="text-red-600 hover:text-red-900"
                        >
                          <TrashIcon className="h-5 w-5" />
                        </Button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        </>
      )}

      {selectedProducto && (
        <VarianteForm
          isOpen={isCreateModalOpen}
          onClose={() => setIsCreateModalOpen(false)}
          onSuccess={handleSuccess}
          productoId={selectedProductoId!}
        />
      )}

      {selectedVariante && (
        <EditVarianteForm
          isOpen={isEditModalOpen}
          onClose={() => {
            setIsEditModalOpen(false);
            setSelectedVariante(null);
          }}
          onSuccess={handleSuccess}
          variante={selectedVariante}
          productoId={selectedProductoId!}
        />
      )}

      <AlertDialog open={isDeleteDialogOpen} onOpenChange={setIsDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>¿Estás seguro?</AlertDialogTitle>
            <AlertDialogDescription>
              Esta acción no se puede deshacer. Se eliminará permanentemente la variante
              {varianteToDelete && ` ${varianteToDelete.ram} - ${varianteToDelete.almacenamiento} - ${varianteToDelete.color}`}.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={loading}>Cancelar</AlertDialogCancel>
            <AlertDialogAction
              onClick={confirmDelete}
              disabled={loading}
              className="bg-red-600 hover:bg-red-700"
            >
              {loading ? 'Eliminando...' : 'Eliminar'}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
};

export default Variantes;
