import axios, { AxiosError, InternalAxiosRequestConfig } from 'axios';
import { useAuthStore } from '@/store/auth-store';

const baseURL = 'http://localhost:5015/';

const api = axios.create({
    baseURL,
    headers: {
        'Content-Type': 'application/json'
    },
    withCredentials: true
});

// Extender la interfaz de configuración de Axios
interface CustomAxiosRequestConfig extends InternalAxiosRequestConfig {
    _retry?: boolean;
}

// Función para verificar si el token está expirado
const isTokenExpired = (token: string): boolean => {
    try {
        const payload = JSON.parse(atob(token.split('.')[1]));
        // Agregar un margen de 5 minutos antes de considerar el token expirado
        return (payload.exp * 1000) < (Date.now() - 5 * 60 * 1000);
    } catch {
        return true;
    }
};

// Interceptor para agregar el token a las peticiones
api.interceptors.request.use(
    (config) => {
        const token = useAuthStore.getState().token;
        if (token) {
            // Solo verificar expiración si no es una petición de login
            if (!config.url?.includes('/Admin/login') && isTokenExpired(token)) {
                // Si el token está expirado, limpiar y redirigir al login
                useAuthStore.getState().logout();
                return Promise.reject(new Error('Token expirado'));
            }
            config.headers.Authorization = `Bearer ${token}`;
        }
        return config;
    },
    (error) => {
        console.error('Error en interceptor de request:', error);
        return Promise.reject(error);
    }
);

// Interceptor para manejar errores
api.interceptors.response.use(
    (response) => response,
    async (error: AxiosError) => {
        const originalRequest = error.config as CustomAxiosRequestConfig;

        // Log del error para debugging
        console.error('Error en la petición:', {
            url: originalRequest?.url,
            method: originalRequest?.method,
            status: error.response?.status,
            data: error.response?.data
        });

        // Si el error es 401 y no es una petición de login
        if (error.response?.status === 401 && !originalRequest?.url?.includes('/Admin/login')) {
            // Limpiar el token solo si no es una petición de login
            useAuthStore.getState().logout();
            // Usar setTimeout para evitar problemas de navegación durante la petición
            setTimeout(() => {
                window.location.href = '/login';
            }, 100);
            return Promise.reject(new Error('Sesión expirada'));
        }

        // Manejo de otros errores comunes
        if (error.response) {
            switch (error.response.status) {
                case 403:
                    console.error('Acceso denegado');
                    break;
                case 404:
                    console.error('Recurso no encontrado');
                    break;
                case 500:
                    console.error('Error del servidor');
                    break;
            }
        } else if (error.request) {
            console.error('No se recibió respuesta del servidor');
        } else {
            console.error('Error en la configuración de la petición:', error.message);
        }

        return Promise.reject(error);
    }
);

export default api; 