import React, { useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import axios from '@/lib/axios';
import { toast } from 'sonner';

interface ProductFormProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess: () => void;
}

interface Producto {
  marca: string;
  modelo: string;
  categoria: string;
  img: File | null;
}

export async function toWebpBase64(file: File, size = 400, quality = 0.8): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        // Crear canvas cuadrado
        const canvas = document.createElement('canvas');
        canvas.width = size;
        canvas.height = size;
        const ctx = canvas.getContext('2d');
        if (!ctx) return reject('No se pudo obtener el contexto del canvas');

        // Calcular tamaño y posición para centrar la imagen
        const scale = Math.min(size / img.width, size / img.height);
        const newWidth = img.width * scale;
        const newHeight = img.height * scale;
        const x = (size - newWidth) / 2;
        const y = (size - newHeight) / 2;

        ctx.fillStyle = '#fff'; // Fondo blanco (opcional)
        ctx.fillRect(0, 0, size, size);
        ctx.drawImage(img, x, y, newWidth, newHeight);

        canvas.toBlob(
          (blob) => {
            if (!blob) return reject('Error al convertir la imagen a WebP');
            const reader2 = new FileReader();
            reader2.onloadend = () => {
              const base64data = reader2.result as string;
              resolve(base64data.split(',')[1]);
            };
            reader2.readAsDataURL(blob);
          },
          'image/webp',
          quality
        );
      };
      img.onerror = () => reject('Error al cargar la imagen');
      img.src = e.target?.result as string;
    };
    reader.onerror = () => reject('Error al leer el archivo');
    reader.readAsDataURL(file);
  });
}

const ProductForm: React.FC<ProductFormProps> = ({ isOpen, onClose, onSuccess }) => {
  const [producto, setProducto] = useState<Producto>({
    marca: '',
    modelo: '',
    categoria: '',
    img: null
  });
  const [loading, setLoading] = useState(false);

  const handleProductoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setProducto(prev => ({ ...prev, [name]: value }));
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setProducto(prev => ({ ...prev, img: e.target.files![0] }));
    }
  };

  const handleSubmit = async () => {
    if (!producto.marca || !producto.modelo || !producto.categoria) {
      toast.error('Todos los campos son requeridos');
      return;
    }

    try {
      setLoading(true);

      let imgBase64 = "";
      if (producto.img) {
        imgBase64 = await toWebpBase64(producto.img, 600, 0.7);
      }

      const productoPayload = {
        marca: producto.marca,
        modelo: producto.modelo,
        categoria: producto.categoria,
        img: imgBase64
      };

      await axios.post('/api/Producto', productoPayload);
      
      toast.success('¡Producto creado exitosamente!', {
        description: 'El producto se ha guardado en el sistema.',
        duration: 4000,
      });
      
      // Reset form
      setProducto({
        marca: '',
        modelo: '',
        categoria: '',
        img: null
      });
      
      onSuccess();
      onClose();
    } catch (error: any) {
      console.error('Error al crear el producto:', error);
      const errorMessage = error.response?.data?.message || error.message || 'Error al crear el producto';
      toast.error(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  const handleClose = () => {
    setProducto({
      marca: '',
      modelo: '',
      categoria: '',
      img: null
    });
    onClose();
  };

  return (
    <Dialog open={isOpen} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle>Crear Nuevo Producto</DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="marca">Marca</Label>
              <Input
                id="marca"
                name="marca"
                value={producto.marca}
                onChange={handleProductoChange}
                placeholder="Ej: Samsung"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="modelo">Modelo</Label>
              <Input
                id="modelo"
                name="modelo"
                value={producto.modelo}
                onChange={handleProductoChange}
                placeholder="Ej: Galaxy S21"
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="categoria">Categoría</Label>
            <Select
              value={producto.categoria}
              onValueChange={(value) => setProducto(prev => ({ ...prev, categoria: value }))}
            >
              <SelectTrigger>
                <SelectValue placeholder="Selecciona una categoría" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="celular">Celular</SelectItem>
                <SelectItem value="tablet">Tablet</SelectItem>
                <SelectItem value="laptop">Laptop</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <Label htmlFor="img">Imagen del Producto</Label>
            <Input
              id="img"
              type="file"
              accept="image/*"
              onChange={handleImageChange}
            />
          </div>

          {producto.img && (
            <div className="space-y-2">
              <Label htmlFor="imgPreview">Vista Previa</Label>
              <img
                src={`data:image/jpeg;base64,${producto.img}`}
                alt={producto.modelo}
                className="w-64 h-64 object-contain mx-auto rounded"
              />
            </div>
          )}
        </div>

        <DialogFooter>
          <Button
            variant="outline"
            onClick={handleClose}
          >
            Cancelar
          </Button>
          <Button
            onClick={handleSubmit}
            disabled={loading || !producto.marca || !producto.modelo || !producto.categoria}
          >
            {loading ? 'Creando...' : 'Crear Producto'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

export default ProductForm; 